// ============================================================
// Sort & Slice Top N by 24h Volume
//
// Filters USDT perpetual pairs, excludes stablecoins and fiat
// pairs, sorts by 24h quote volume descending, and returns
// the top N symbols. Resets the global staticData accumulator
// before the loop begins.
// ============================================================

// --- Configuration ---
const TOP_N = 20;

const BLACKLIST_SYMBOLS = new Set([
  'USDCUSDT','BUSDUSDT','TUSDUSDT','USDPUSDT','FDUSDUSDT',
  'DAIUSDT','USDDUSDT','FRAXUSDT','LUSDUSDT','GUSDUSDT',
  'SUSDUSDT','USTCUSDT','EURUSDT','EUROCUSDT','EURSUSDT',
  'AGEURUSDT','GBPTUSDT','JPYCUSDT','CNHTUSDT','XSGDUSDT',
  'NZDSUSDT','CADCUSDT','TRYBUSDT','BRLAUSDT','IDRTUSDT','BIDRUSDT',
]);

const FIAT_PATTERNS = [
  'USD','EUR','JPY','GBP','AUD','CAD','CHF','CNY','CNH','KRW',
  'TRY','BRL','IDR','SGD','NZD','HKD','SEK','NOK','DKK','PLN',
  'CZK','MXN','ZAR','THB','PHP','INR','RUB',
];

// --- Filter ---
const tickers = $input.all().map(item => item.json);

const filtered = tickers.filter(t => {
  const sym = t.symbol;
  if (!sym.endsWith('USDT')) return false;
  if (BLACKLIST_SYMBOLS.has(sym)) return false;
  const base = sym.slice(0, -4);
  if (FIAT_PATTERNS.some(fiat =>
    base === fiat || base.startsWith(fiat) || base.endsWith(fiat)
  )) return false;
  return true;
});

// --- Sort by 24h quote volume (USDT) descending ---
filtered.sort((a, b) =>
  parseFloat(b.quoteVolume) - parseFloat(a.quoteVolume)
);

const topN = filtered.slice(0, TOP_N);

// --- Reset accumulator before loop starts ---
const sd = $getWorkflowStaticData('global');
sd.oi_results = [];

return topN.map(t => ({
  json: {
    symbol: t.symbol,
    quoteVolume: parseFloat(t.quoteVolume),
    priceChangePercent: parseFloat(t.priceChangePercent),
    lastPrice: parseFloat(t.lastPrice)
  }
}));

// ============================================================
// Accumulate OI Change Data
//
// Runs inside the loop body. Receives 2 OI history data points
// (latest and 1h ago), calculates the percentage change in OI
// value (USDT), classifies the alert level, and pushes the
// result into the global staticData accumulator.
// Output connects back to Loop Over Items for the next iteration.
// ============================================================

// --- Thresholds (adjust to taste) ---
const WARNING_THRESHOLD  = 3.0;  // 3%
const CRITICAL_THRESHOLD = 7.0;  // 7%

// --- Accumulator guard ---
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.oi_results)) sd.oi_results = [];

// openInterestHist returns an array — n8n splits each element into an item
// limit=2 → 2 items: index 0 = 1h ago, index 1 = latest
const items = $input.all();

if (!items || items.length < 2) {
  return [{ json: { skipped: true } }];
}

const latest = items[items.length - 1].json;
const prev   = items[0].json;

if (!latest.symbol || !latest.sumOpenInterestValue || !prev.sumOpenInterestValue) {
  return [{ json: { skipped: true } }];
}

const symbol = latest.symbol;
const oiNow  = parseFloat(latest.sumOpenInterestValue); // OI in USDT
const oiPrev = parseFloat(prev.sumOpenInterestValue);

// Percentage change based on USDT notional value
const pctChange    = ((oiNow - oiPrev) / oiPrev) * 100;
const absPct       = Math.abs(pctChange);
const pctFormatted = pctChange.toFixed(2);

const direction = pctChange >= 0 ? 'increasing' : 'decreasing';
const dirIcon   = pctChange >= 0 ? '📈' : '📉';

// Format OI value with B/M suffix
function formatUSD(val) {
  if (val >= 1e9) return `$${(val / 1e9).toFixed(2)}B`;
  if (val >= 1e6) return `$${(val / 1e6).toFixed(2)}M`;
  return `$${val.toFixed(0)}`;
}

let level = 'normal';
if (absPct >= CRITICAL_THRESHOLD)     level = 'critical';
else if (absPct >= WARNING_THRESHOLD) level = 'warning';

sd.oi_results.push({
  symbol, pctChange, pctFormatted, absPct,
  oiNow, oiNowDisplay: formatUSD(oiNow),
  direction, dirIcon, level
});

return [{ json: { symbol, level, pctFormatted } }];

// ============================================================
// Process Results + Format Telegram Message
//
// Runs once after the Done branch of Loop Over Items.
// Reads all accumulated OI data from global staticData,
// splits into critical / warning tiers sorted by absolute
// change, builds an HTML message for Telegram, and resets
// the accumulator for the next run.
// ============================================================

// --- Thresholds (must match Accumulate node) ---
const WARNING_THRESHOLD  = 3.0;
const CRITICAL_THRESHOLD = 7.0;

// --- Read and reset accumulator ---
const sd = $getWorkflowStaticData('global');
const allResults = Array.isArray(sd.oi_results) ? [...sd.oi_results] : [];
sd.oi_results = [];

// --- Classify ---
const criticals = allResults
  .filter(r => r.level === 'critical')
  .sort((a, b) => b.absPct - a.absPct);

const warnings = allResults
  .filter(r => r.level === 'warning')
  .sort((a, b) => b.absPct - a.absPct);

const alertCount = criticals.length + warnings.length;

if (alertCount === 0) {
  return [{ json: { hasAlerts: false, message: '' } }];
}

// --- Format ---
const timestamp = new Date().toLocaleString('en-GB', {
  timeZone: 'Asia/Ho_Chi_Minh',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false
});

function formatCoin(r) {
  const icon = r.level === 'critical' ? '🔴' : '🟡';
  const sign = r.pctChange >= 0 ? '+' : '';
  return `${icon} <b>${r.symbol}</b>: <code>${sign}${r.pctFormatted}%</code> ${r.dirIcon} OI ${r.direction} | ${r.oiNowDisplay}`;
}

const lines = [];
lines.push(`📊 <b>Open Interest Monitor</b>`);
lines.push(`🕐 ${timestamp} (ICT)`);
lines.push(`🔍 Scanned: top ${allResults.length} USDT perps by 24h volume`);
lines.push(`⏱ Lookback: 1h`);
lines.push(``);

if (criticals.length > 0) {
  lines.push(`🔴 <b>CRITICAL (≥${CRITICAL_THRESHOLD}%)</b> — ${criticals.length} coin${criticals.length > 1 ? 's' : ''}`);
  lines.push(`${'─'.repeat(28)}`);
  criticals.forEach(r => lines.push(formatCoin(r)));
  lines.push(``);
}

if (warnings.length > 0) {
  lines.push(`🟡 <b>WARNING (≥${WARNING_THRESHOLD}%)</b> — ${warnings.length} coin${warnings.length > 1 ? 's' : ''}`);
  lines.push(`${'─'.repeat(28)}`);
  warnings.forEach(r => lines.push(formatCoin(r)));
}

return [{
  json: {
    hasAlerts: true,
    alertCount,
    message: lines.join('\n')
  }
}];
